{
  "name": "规则任务调度服务器",
  "name_en": "Rule-Based Task Scheduling Server",
  "manufacturer": "",
  "description": "非物理软件组件，用于在 PYME 集群分析流程中按规则生成和发布任务，接收计算节点竞价，释放或停用任务规则，并汇总任务完成状态。适用于显微成像等实验数据的分布式处理与工作流调度。",
  "description_en": "A non-physical software component that generates and advertises tasks according to rules in a PYME cluster workflow, accepts bids from compute nodes, releases or inactivates task rules, and collects task completion results. It is used for distributed processing and workflow scheduling of experimental data such as microscopy analysis.",
  "actions": [
    {
      "action_name": "auto-stop",
      "description": "停止规则任务服务器。",
      "description_en": "Stop the rule task server."
    },
    {
      "action_name": "auto-task_advertisements",
      "description": "获取当前可供工作节点竞价的任务广告列表。",
      "description_en": "Retrieve the current list of task advertisements available for worker-node bidding."
    },
    {
      "action_name": "auto-bid_on_tasks",
      "description": "提交计算节点对任务的竞价信息，以申请执行任务。",
      "description_en": "Submit a compute node's bids on tasks to request task execution."
    },
    {
      "action_name": "auto-add_integer_id_rule",
      "description": "添加基于整数 ID 生成任务的规则，用于批量创建分析或配方任务。",
      "description_en": "Add a rule that generates tasks from integer IDs for bulk creation of analysis or recipe tasks."
    },
    {
      "action_name": "auto-release_rule_tasks",
      "description": "释放指定规则下某一范围的任务，使其可被集群节点领取执行。",
      "description_en": "Release a specified range of tasks under a rule so that cluster nodes can claim and execute them."
    },
    {
      "action_name": "auto-inactivate_rule",
      "description": "将指定规则置为失效或停止，阻止其继续分发任务。",
      "description_en": "Inactivate or stop a specified rule to prevent further task distribution."
    },
    {
      "action_name": "auto-handin",
      "description": "提交任务完成回执，将任务标记为已完成。",
      "description_en": "Submit task completion reports to mark tasks as finished."
    },
    {
      "action_name": "auto-mark_release_complete",
      "description": "标记某条规则的任务释放过程已完成，表示不会再新增任务。",
      "description_en": "Mark task release for a rule as complete, indicating that no more tasks will be added."
    },
    {
      "action_name": "auto-status",
      "description": "获取规则任务服务器的当前状态。",
      "description_en": "Retrieve the current status of the rule task server."
    }
  ],
  "tag_hints": [
    "rule-based job scheduling",
    "distributed analysis workflow",
    "task advertisement and bidding",
    "cluster task dispatch",
    "HTTP API server",
    "PYME workflow",
    "microscopy data processing"
  ]
}

